package core

import (
	"bytes"
	"slices"
	"strings"
)

func generatedLinePrefixes() []string {
	return []string{"//", "#", "--"}
}

func generatedBlockDelims() []BlockDelim {
	return []BlockDelim{
		{Open: "/*", Close: "*/"},
		{Open: "<!--", Close: "-->"},
		{Open: "--[[", Close: "]]"},
	}
}

func generatedPhrases() []string {
	return []string{
		"GENERATED CODE - DO NOT MODIFY BY HAND",
		"AUTO-GENERATED FILE",
		"@generated",
		"<auto-generated",
	}
}

func IsGeneratedSource(src []byte) bool {
	var openBlock *BlockDelim
lines:
	for line := range bytes.Lines(src) {
		rest := strings.TrimSpace(string(line))
		for {
			switch {
			case openBlock != nil:
				closeIdx := strings.Index(rest, openBlock.Close)
				if closeIdx == -1 {
					continue lines
				}
				rest = strings.TrimSpace(rest[closeIdx+len(openBlock.Close):])
				openBlock = nil
			case rest == "":
				continue lines
			default:
				block, isOpen := openingGeneratedBlock(rest)
				if isOpen {
					rest = strings.TrimSpace(rest[len(block.Open):])
					openBlock = &block
					continue
				}
				prefix, isLine := matchingLinePrefix(rest)
				if !isLine {
					// The first line of real code (for Go, the package
					// clause). The marker is only honoured above it, and
					// so is this scan.
					return false
				}
				if isGeneratedMarker(strings.TrimSpace(rest[len(prefix):])) {
					return true
				}
				continue lines
			}
		}
	}
	return false
}

func openingGeneratedBlock(rest string) (BlockDelim, bool) {
	for _, block := range generatedBlockDelims() {
		if strings.HasPrefix(rest, block.Open) {
			return block, true
		}
	}
	return BlockDelim{}, false
}

func matchingLinePrefix(rest string) (string, bool) {
	for _, prefix := range generatedLinePrefixes() {
		if strings.HasPrefix(rest, prefix) {
			return prefix, true
		}
	}
	return "", false
}

func isGeneratedMarker(content string) bool {
	const (
		generatedPrefix = "Code generated "
		generatedSuffix = " DO NOT EDIT."
	)
	if len(content) >= len(generatedPrefix)+len(generatedSuffix) &&
		strings.HasPrefix(content, generatedPrefix) &&
		strings.HasSuffix(content, generatedSuffix) {
		return true
	}
	return slices.ContainsFunc(generatedPhrases(), func(phrase string) bool {
		return strings.Contains(content, phrase)
	})
}

func directiveHeaderPrefixes() []string {
	return []string{
		"//go:build", "// +build", "//go:generate", "//go:embed", "//nolint:",
		"//lint:ignore ", "//lint:file-ignore ",
		"/// <reference", "/// <amd-module", "/// <amd-dependency",
		"// @vitest-environment", "// @ts-self-types=",
		"/* istanbul ignore file", "/* c8 ignore", "/* v8 ignore file",
		"// coverage:ignore-file", "// ignore_for_file:", "// @dart=", "// @dart =",
		"// @ts-nocheck", "// @ts-check", "// @ts-ignore", "// @ts-expect-error",
		"// eslint-disable", "/* eslint", "// prettier-ignore",
		"// deno-lint-ignore-file", "// deno-fmt-ignore-file",
		"// protolint:disable", "// buf:lint:ignore",
		"<!-- svelte-ignore", "#!", "# -*- coding:", "# coding:",
	}
}

const SimplificationMarker = "simplification:"

func IsSimplificationMarker(line string) bool {
	trimmed := strings.TrimSpace(line)
	for _, prefix := range []string{"//", "#", "--"} {
		if comment, ok := strings.CutPrefix(trimmed, prefix); ok {
			return strings.HasPrefix(strings.TrimSpace(comment), SimplificationMarker)
		}
	}
	return false
}

func IsExemptHeaderLine(line string) bool {
	trimmed := strings.TrimSpace(line)
	if isGeneratedMarkerLine(trimmed) {
		return true
	}
	return isSQLCAnnotation(trimmed) || slices.ContainsFunc(
		directiveHeaderPrefixes(),
		func(prefix string) bool { return strings.HasPrefix(trimmed, prefix) },
	)
}

func isSQLCAnnotation(trimmed string) bool {
	body, ok := strings.CutPrefix(trimmed, "-- name: ")
	if !ok {
		return false
	}
	// The sqlc tool splits on single spaces, so repeated spaces are not an annotation.
	fields := strings.Split(body, " ")
	if len(fields) != 2 {
		return false
	}
	command, ok := strings.CutPrefix(fields[1], ":")
	if !ok {
		return false
	}
	switch command {
	case "one", "many", "exec", "execrows", "execresult", "execlastid",
		"copyfrom", "batchexec", "batchmany", "batchone":
		return true
	}
	return false
}

func isGeneratedMarkerLine(trimmed string) bool {
	prefix, ok := matchingLinePrefix(trimmed)
	if !ok {
		return false
	}
	return isGeneratedMarker(strings.TrimSpace(trimmed[len(prefix):]))
}
